<script setup lang="ts">
import UiButton from './UiButton.vue';
import {onMounted,onBeforeUnmount,computed,ref} from 'vue';
import {screenResultIsStale} from './screen-state.mjs';
import ScreenPreparationPanel from './ScreenPreparationPanel.vue';
import type {ScreenCondition,ScreenPage,Watchlist} from '../../../../packages/contracts/desktop';
defineProps<{groups:Watchlist[]}>();const emit=defineEmits<{changed:[];open:[id:string]}>();
const date=ref(new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date())),conditions=ref<ScreenCondition[]>([{field:'price',operator:'gte',value:0}]);
const sort=ref('price'),direction=ref('desc'),name=ref(''),definitions=ref<{name:string;conditions:ScreenCondition[]}[]>([]),result=ref<ScreenPage|null>(null),busy=ref(false),error=ref(''),group=ref(''),notice=ref('');
const fields=[['price','价格 / 元'],['amount','成交额 / 元'],['total_mv','总市值 / 元'],['pe','PE / 倍'],['pb','PB / 倍'],['ma20Ratio','收盘价 / MA20'],['ma60Ratio','收盘价 / MA60']];
const desktop=Boolean(window.stock);
const operation=ref(''),elapsed=ref(0);let timer:ReturnType<typeof setInterval>|undefined,closed=false;
const stale=computed(()=>screenResultIsStale({date:date.value,conditions:conditions.value,sort:sort.value,direction:direction.value},result.value));
onBeforeUnmount(()=>{closed=true;clearInterval(timer)});
async function action(label:string,fn:()=>Promise<void>){if(!window.stock||busy.value)return;busy.value=true;operation.value=label;elapsed.value=0;const started=Date.now();timer=setInterval(()=>{elapsed.value=Math.floor((Date.now()-started)/1000)},1000);error.value='';notice.value='';try{await fn()}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{clearInterval(timer);if(!closed)busy.value=false}}
async function run(){await action('正在运行筛选',async()=>{const next=await window.stock!.runScreen(date.value.replaceAll('-',''),JSON.parse(JSON.stringify(conditions.value)),sort.value,direction.value);if(!closed)result.value=next})}
async function page(offset:number){if(!result.value)return;await action('正在读取结果页',async()=>{const next=await window.stock!.screenPage(result.value!.resultId,offset);if(!closed)result.value=next})}
async function save(){await action('正在保存条件',async()=>{const next=await window.stock!.saveScreen(name.value,JSON.parse(JSON.stringify(conditions.value)));if(!closed){definitions.value=next;notice.value='筛选条件已保存。'}})}
async function add(code:string){await action('正在加入自选',async()=>{await window.stock!.addWatchlistMember(group.value,code);if(!closed){notice.value=code+' 已加入分组。';emit('changed')}})}
const format=(n:number|null)=>n===null?'—':n.toLocaleString('zh-CN',{maximumFractionDigits:2});
onMounted(()=>action('正在恢复上次结果',async()=>{const [saved,latest]=await Promise.all([window.stock!.screenDefinitions(),window.stock!.latestScreen()]);if(!closed){definitions.value=saved;result.value=latest;if(latest){date.value=latest.date;conditions.value=JSON.parse(JSON.stringify(latest.conditions));sort.value=latest.sort;direction.value=latest.direction;notice.value='已恢复最近一次成功筛选结果。';date.value=latest.date.slice(0,4)+'-'+latest.date.slice(4,6)+'-'+latest.date.slice(6,8)}}}));
</script>
<template><section class="screen-panel"><p class="section-footnote">在已同步股票中筛选，全部条件同时满足。价格、市值、成交额均为元。PE 条件排除缺失和非正值；均线比值 ≥ 1 表示收盘价不低于均线。</p><div class="screen-controls"><label>交易日 <input :disabled="busy" v-model="date" type="date"></label><label>排序 <select :disabled="busy" v-model="sort"><option v-for="[key,label] in fields" :key="key" :value="key">{{label}}</option></select></label><select :disabled="busy" v-model="direction" aria-label="排序方向"><option value="desc">降序</option><option value="asc">升序</option></select></div><div v-for="(condition,index) in conditions" :key="index" class="screen-controls"><select :disabled="busy" v-model="condition.field" :aria-label="'条件字段 '+(index+1)"><option v-for="[key,label] in fields" :key="key" :value="key">{{label}}</option></select><select :disabled="busy" v-model="condition.operator" :aria-label="'比较运算 '+(index+1)"><option value="gte">≥</option><option value="lte">≤</option><option value="gt">&gt;</option><option value="lt">&lt;</option></select><input :disabled="busy" v-model.number="condition.value" type="number" step="any" :aria-label="'比较数值 '+(index+1)"><UiButton icon="trash" :disabled="conditions.length===1||busy" @click="conditions.splice(index,1)">移除条件</UiButton></div><div class="screen-controls"><UiButton icon="plus" :disabled="conditions.length>=10||busy" @click="conditions.push({field:'pe',operator:'lte',value:20})">添加条件</UiButton><UiButton icon="chevron" class="primary" :disabled="!desktop||busy" @click="run">{{busy?'处理中…':'运行筛选'}}</UiButton><input v-model="name" maxlength="40" placeholder="条件名称" aria-label="保存条件名称"><UiButton icon="save" :disabled="!desktop||busy||!name.trim()" @click="save">保存条件</UiButton></div><div v-if="definitions.length" class="screen-controls"><span>已保存</span><button v-for="item in definitions" :key="item.name" :disabled="busy" @click="conditions=JSON.parse(JSON.stringify(item.conditions));name=item.name">{{item.name}}</button></div><p v-if="busy" class="section-footnote" role="status" aria-live="polite">{{operation}} · 已等待 {{elapsed}} 秒。计算期间可切换页面；切换页面不会取消已提交的计算。</p><p v-if="stale" class="section-footnote" role="status">条件已修改，下方仍是上次运行结果。请重新运行筛选。</p><p v-if="error" class="banner error" role="alert">{{error}}</p><p v-if="notice" class="banner success" role="status">{{notice}}</p><template v-if="result"><p class="section-footnote">{{result.date}} · 匹配 {{result.total}} 只 · 当日日线覆盖 {{result.covered}} / 目录 {{result.catalogCount}} 只 · 已有快照但缺当日记录 {{result.missingDate}} 只<br><span v-if="busy">下方保留上次结果。 </span>结果 {{result.resultId.slice(0,16)}} · 修改条件后需重新运行。分页保持此结果不变。</p><div class="screen-controls"><label>加入分组 <select v-model="group"><option value="">选择自选分组</option><option v-for="g in groups" :key="g.id" :value="g.id">{{g.name}}</option></select></label></div><div class="result-table"><table><thead><tr><th>股票</th><th>价格</th><th>PE</th><th>PB</th><th>总市值 / 元</th><th>操作</th></tr></thead><tbody><tr v-for="row in result.items" :key="row.id"><td><UiButton icon="chevron" class="text-button" @click="emit('open',row.id)">{{row.name}}</UiButton><small>{{row.id}}</small></td><td>{{format(row.price)}}</td><td>{{format(row.pe)}}</td><td>{{format(row.pb)}}</td><td>{{format(row.total_mv)}}</td><td><UiButton icon="chevron" :disabled="!group||busy" @click="add(row.id)">加入自选</UiButton></td></tr></tbody></table></div><div class="screen-controls"><UiButton icon="chevron" :disabled="busy||result.offset===0" @click="page(result.offset-50)">上一页</UiButton><span>{{result.total?result.offset+1:0}}–{{Math.min(result.offset+50,result.total)}} / {{result.total}}</span><UiButton icon="chevron" :disabled="busy||result.offset+50>=result.total" @click="page(result.offset+50)">下一页</UiButton></div></template><ScreenPreparationPanel :groups="groups" :date="date"/></section></template>
<style scoped>.screen-controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:14px 24px;font-size:0.923077rem}.screen-controls input[type=number]{width:140px}.result-table{overflow:auto}table{min-width:600px}small{display:block;color:var(--muted);font:0.846154rem Consolas,monospace;margin-top:5px}td{font-variant-numeric:tabular-nums}</style>
